const now = new Date();
// Chuyển sang giờ Việt Nam (UTC+7)
const hour = (now.getUTCHours() + 7) % 24;

let topic = 'focus';
let topicName = 'Tập Trung Sâu & Trị Sương Mù Não';

if (hour >= 18 || hour < 5) {
  topic = 'habit';
  topicName = 'Xây Dựng Thói Quen & Kỷ Luật Không Gồng';
}

return [{
  json: {
    topic: topic,
    topicName: topicName,
    hour: hour,
    executedAt: now.toISOString()
  }
}];

const res = $input.first().json;
const topicData = $('Xác Định Chủ Đề (Focus/Habit)').first().json;

const rawOut = String(res.stdout_snippet || '') + '\n' + String(res.stderr_snippet || '');
const auditFailed = /LỖI KIỂM TOÁN|THẤT LẠC BÀI VIẾT|Đã hoàn tác|TỪ CHỐI BUILD|TỪ CHỐI DEPLOY/i.test(rawOut);
const isSuccess = res.status === 'success' && Number(res.returncode) === 0 && !auditFailed;

const esc = (s) => String(s)
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, ' ')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const webUrl = res.website_url || 'https://traicainghien.com/bai-viet';

let msg = isSuccess
  ? `🚀 <b>MÂY N8N — FLOW 03 ĐÃ XUẤT BẢN THÀNH CÔNG!</b>\n\n`
  : `⚠️ <b>MÂY N8N — FLOW 03 CHƯA XUẤT BẢN ĐƯỢC BÀI NÀO</b>\n\n`;

msg += `📌 <b>Trạng thái:</b> ${isSuccess ? '✅ THÀNH CÔNG' : '⚠️ CẦN BỐ KIỂM TRA'}\n`;
msg += `🏷 <b>Chủ đề:</b> [${esc(topicData.topicName)}]\n`;
msg += `🌐 <b>Website:</b> ${esc(webUrl)}\n`;
const fbId = String(res.facebook_post_id || '');
const fbLine = (fbId && fbId !== 'FAILED')
  ? `📘 <b>Fanpage:</b> ✅ Đã đăng — <a href="https://www.facebook.com/traicainghienvn2026">facebook.com/traicainghienvn2026</a>\n`
  : (fbId === 'FAILED'
     ? `📘 <b>Fanpage:</b> ⚠️ Đăng lỗi — bài đã vào hàng đợi, Mây sẽ đăng lại\n`
     : `📘 <b>Fanpage:</b> <a href="https://www.facebook.com/traicainghienvn2026">facebook.com/traicainghienvn2026</a>\n`);
msg += fbLine;
msg += `📢 <b>Telegram Channel:</b> @traicainghiendaily\n`;

if (!isSuccess) {
  const tail = rawOut.split('\n').map(l => l.trim()).filter(Boolean).slice(-8).join('\n').slice(0, 600);
  msg += `\n🧾 <b>Nhật ký lỗi (rút gọn):</b>\n<pre>${esc(tail)}</pre>\n`;
  msg += `\n👉 <i>Mây đã giữ nguyên bản cũ trên website, chưa deploy bản lỗi.</i>`;
} else {
  msg += `\n🌱 <i>Bộ máy tự động n8n đã hoàn tất toàn bộ chu trình cào video, viết bài, deploy web và phát sóng đa kênh!</i>`;
}

return [{
  json: {
    chat_id: '488901419',
    text: msg,
    parse_mode: 'HTML'
  }
}];
